// ffxiii2 - Final Fantasy XIII-2 (Europe, TU6), ReXGlue recompiled project.
// Stage 3 (first boot, emulated GPU): the SDK's app as generated by `rexglue init`, no game hooks yet.
// Hooks are added only for crashes the boot tests show, each with its evidence (see docs/).
#pragma once

#include <rex/rex_app.h>

class Ffxiii2App : public rex::ReXApp {
 public:
  using rex::ReXApp::ReXApp;

  static std::unique_ptr<rex::ui::WindowedApp> Create(rex::ui::WindowedAppContext& ctx) {
    return std::unique_ptr<Ffxiii2App>(new Ffxiii2App(ctx, "ffxiii2", PPCImageConfig));
  }
};
